/* PDF "Confirmação de Pedido" no modelo da Capricórnio (impressão do portal), gerado a partir das
   linhas da carteira. Uso: PedidoPDF.gerar(JsPDF, linhas, {representante, saudacao}) -> {blob, nome}.
   Campos que a carteira não traz (endereço de entrega, antecipação, data base, forma de pagamento)
   ficam de fora. */
(function(){
'use strict';
var A = {"logo": "data:image/png;base64,", "coracao": "data:image/png;base64,", "maos": "data:image/png;base64,", "logoW": 760, "logoH": 175};
var LINHAS = {"ALCARAZ": "COMFORT DENIM", "BOSCO": "COMFORT DENIM", "IBIRA": "COMFORT DENIM", "GUGA": "COMFORT DENIM", "NADAL": "COMFORT DENIM", "LEE": "COLOR", "MONTE": "COLOR", "LAMAR": "COMFORT DENIM", "FEBE": "FLAT COMFORT DENIM", "ALLOS": "FLAT COLOR", "MIRA": "FLAT COLOR", "RUES": "FLAT COLOR", "LIZ": "LIGHT DENIM", "LUNA": "ECO DENIM", "EVA": "LIGHT DENIM", "GRACA": "COLOR", "JERI": "ORIGINAL DENIM", "LAPA": "COLOR", "PIPA": "ORIGINAL DENIM", "ARAGUAIA": "ORIGINAL DENIM", "ALBATROZ": "ORIGINAL DENIM", "ALGARVE": "ORIGINAL DENIM", "ATINS": "ORIGINAL DENIM", "BRAVA": "ORIGINAL DENIM", "GERIBA": "ORIGINAL DENIM", "GLORIA": "ORIGINAL DENIM", "PREA": "ORIGINAL DENIM", "SAGI": "ORIGINAL DENIM", "TAIBA": "ORIGINAL DENIM", "TANGUA": "ORIGINAL DENIM", "UNA": "ORIGINAL DENIM", "GUIMAS": "POLI COMFORT DENIM", "RUDA": "POLI COMFORT DENIM", "ADONIS": "POLI COMFORT DENIM", "ORFEU": "POLI COMFORT DENIM", "VIELA": "POLI COMFORT DENIM", "BARTO": "POLI COMFORT DENIM", "TRANCOSO": "POLI COMFORT DENIM", "RIO": "POLI COMFORT DENIM", "BORBA": "ORIGINAL DENIM", "BRAGA": "ORIGINAL DENIM", "CIPO": "ORIGINAL DENIM", "TRINDADE": "ORIGINAL DENIM", "UBA": "ORIGINAL DENIM", "CRATO": "ORIGINAL DENIM", "BARDEM": "COMFORT DENIM", "VIDAL": "COMFORT DENIM"};
var ENDERECO = 'Avenida Angélica, 2248, 9º andar, Consolação, São Paulo - SP, 01228-200';
function norm(t){ return String(t||'').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g,''); }
function linhaDe(desc){ var w=norm(desc).split(/\s+/)[0]; var l=LINHAS[w]||''; return {linha:l, classe: l? (/COLOR/.test(l)?'Color':'Denim') : 'Denim'}; }
function n2(v){ return Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}); }
function pad(x){ return (x<10?'0':'')+x; }
function dt(iso){ return /^\d{4}-\d{2}-\d{2}/.test(iso||'')? iso.slice(8,10)+'/'+iso.slice(5,7)+'/'+iso.slice(0,4) : (iso||''); }
function digitos(c){ return String(c||'').replace(/\D/g,'').replace(/^0+(?=\d{14}$)/,''); }
function gerar(JsPDF, linhas, o){
  o=o||{};
  var vivas=linhas.filter(function(r){ return !/cancel/i.test(r.sitLinha||''); }); if(!vivas.length) vivas=linhas;
  var r0=linhas[0], ped=String(r0.pedido);
  var doc=new JsPDF({unit:'pt', format:'a4', orientation:'portrait'}), W=595.28, H=841.89, L=46, R=W-46, y;
  var agora=new Date(), carimbo=pad(agora.getDate())+'/'+pad(agora.getMonth()+1)+'/'+agora.getFullYear()+', '+pad(agora.getHours())+':'+pad(agora.getMinutes());
  var titulo='Capricórnio Textil - Pedido '+ped;
  doc.setProperties({title:titulo});
  var cinza=function(){ doc.setTextColor(60,60,60); }, preto=function(){ doc.setTextColor(17,17,17); };
  var fonte=function(b,s){ doc.setFont('helvetica', b?'bold':'normal'); doc.setFontSize(s); };
  var topo=function(){ fonte(false,7); doc.setTextColor(40,40,40); doc.text(carimbo, 22, 18); doc.text(titulo, W/2, 18, {align:'center'}); };
  topo();
  /* cabeçalho */
  doc.addImage(A.logo,'PNG',L+6,34,136,136*A.logoH/A.logoW);
  fonte(false,6.3); cinza(); doc.text(ENDERECO, L, 86);
  fonte(true,8.6); preto(); doc.text('Confirmação de Pedido', R, 56, {align:'right'});
  fonte(false,8.6); cinza(); doc.text('Pedido nº: '+ped, R, 70, {align:'right'});
  doc.setDrawColor(200,200,200); doc.setLineWidth(.8); doc.line(L-4, 101, R+4, 101);
  /* saudação */
  fonte(true,7.6); preto(); doc.text('Olá, '+(o.saudacao||r0.grupo||r0.cliente||''), L, 117);
  fonte(false,7.8); doc.setTextColor(40,40,40);
  doc.text('Passando para informar que recebemos seu pedido.', L, 138);
  var t2='Ótima escolha. Eu, particularmente, amo esse(s) produto(s) que você escolheu! ';
  doc.text(t2, L, 151); doc.addImage(A.coracao,'PNG', L+doc.getTextWidth(t2)+3.5, 144, 9, 9);
  doc.line(L-4, 179, R+4, 179);
  /* dados do cliente (esquerda) */
  var lado=function(rot, val, x, yy, maxW){ fonte(false,7.8); doc.setTextColor(40,40,40); doc.text(rot, x, yy); var w=doc.getTextWidth(rot)+2; fonte(true,7.8); preto();
    var ls=doc.splitTextToSize(val, maxW-w); doc.text(ls[0]||'', x+w, yy); for(var i=1;i<ls.length;i++) doc.text(ls[i], x, yy+i*12.5); return yy+ls.length*12.5; };
  y=196;
  y=lado('Cliente: ', (r0.cliente||'')+(r0.cnpj? ' - '+digitos(r0.cnpj):''), L, y, 260);
  y=lado('Representante: ', o.representante||'', L, y+8, 300);
  fonte(false,7.8); doc.setTextColor(40,40,40); doc.text('Endereço de entrega:', L, y+10); y+=22.5;
  fonte(true,7.8); preto();
  var ent=r0.remessa? [r0.remessa, r0.cnpjRem? 'CNPJ '+digitos(r0.cnpjRem):''] : [r0.cliente||'', r0.cnpj? 'CNPJ '+digitos(r0.cnpj):''];
  ent.filter(Boolean).forEach(function(t){ doc.splitTextToSize(t, 270).forEach(function(l){ doc.text(l, L, y); y+=12.5; }); });
  var yEsq=y;
  /* dados do pedido (direita) */
  var dir=function(rot, val, yy){ fonte(true,7.8); preto(); doc.text(String(val), R, yy, {align:'right'}); var w=doc.getTextWidth(String(val)); fonte(false,7.8); doc.setTextColor(40,40,40); doc.text(rot, R-w-1.5, yy, {align:'right'}); };
  var yr=196, oc=r0.oc||r0.pedCli||'';
  if(oc){ dir('Ordem de compra: ', oc, yr); yr+=12.5; }
  dir('Data do pedido: ', dt(r0.emissao), yr); yr+=12.5;
  dir('Data do faturamento: ', dt(r0.embarque), yr); yr+=24;
  if(r0.cond){ dir('Condição: ', r0.cond, yr); yr+=12.5; }
  /* itens */
  y=Math.max(yEsq, yr)+34;
  var cab=function(){ fonte(false,7.8); doc.setTextColor(40,40,40);
    doc.text('SKU', L+4, y); doc.text('Produto / Linha', 182, y); doc.text('Valor Venda', 403, y, {align:'right'}); doc.text('Metragem', 470, y, {align:'right'}); doc.text('Subtotal', R-4, y, {align:'right'});
    doc.setDrawColor(200,200,200); doc.line(L-4, y+9, R+4, y+9); y+=26; };
  cab();
  var tq=0, tv=0;
  vivas.forEach(function(r){
    if(y>H-110){ doc.addPage(); topo(); y=60; cab(); }
    var li=linhaDe(r.desc), sub=(r.qtd||0)*(r.unit||0); tq+=r.qtd||0; tv+=sub;
    fonte(true,7.8); preto();
    doc.text(String(r.sku||''), L+4, y); doc.text(String(r.desc||''), 182, y, {maxWidth:170});
    doc.text(n2(r.unit), 403, y, {align:'right'}); doc.text(n2(r.qtd), 470, y, {align:'right'}); doc.text(n2(sub), R-4, y, {align:'right'});
    fonte(false,5.8); doc.setTextColor(40,40,40); doc.text('Classificação: ', L+4, y+13); var w=doc.getTextWidth('Classificação: '); fonte(true,5.8); preto(); doc.text(li.classe, L+4+w, y+13);
    if(li.linha) doc.text(li.linha, 182, y+13);
    doc.setDrawColor(215,215,215); doc.line(L-4, y+22, R+4, y+22); y+=37;
  });
  fonte(false,7.8); doc.setTextColor(40,40,40); doc.text(vivas.length+' item(s), total:', 403, y-2, {align:'right'});
  fonte(true,7.8); preto(); doc.text(n2(tq), 470, y-2, {align:'right'}); doc.text(n2(tv), R-4, y-2, {align:'right'});
  doc.setDrawColor(215,215,215); doc.line(L-4, y+8, R+4, y+8);
  /* rodapé */
  y+=56; fonte(false,7.8); doc.setTextColor(40,40,40);
  var ob='Obrigada por escolher a Capricórnio! '; var ow=doc.getTextWidth(ob)+10;
  doc.text(ob, W/2-ow/2, y); doc.addImage(A.maos,'PNG', W/2-ow/2+doc.getTextWidth(ob)+3, y-7.5, 9.5, 9.5);
  y+=24; doc.setTextColor(0,102,204); doc.text('www.capricornio.com.br', W/2, y, {align:'center'});
  var lw=doc.getTextWidth('www.capricornio.com.br'); doc.setDrawColor(0,102,204); doc.setLineWidth(.5); doc.line(W/2-lw/2, y+1.5, W/2+lw/2, y+1.5);
  doc.link(W/2-lw/2, y-8, lw, 10, {url:'https://www.capricornio.com.br'});
  var np=doc.internal.getNumberOfPages();
  for(var i=1;i<=np;i++){ doc.setPage(i); fonte(false,7); doc.setTextColor(40,40,40); doc.text(i+'/'+np, W-22, H-14, {align:'right'}); }
  return {blob:doc.output('blob'), nome:titulo+'.pdf'};
}
window.PedidoPDF={gerar:gerar};
})();
